codeExamples.code:
let x = 5;
let y = 10;

console.log('Equal:', x == y);      // false
console.log('Not equal:', x != y);   // true
console.log('Greater than:', x > y); // false
console.log('Less than:', x < y);    // true
console.log('Greater or equal:', x >= y); // false
console.log('Less or equal:', x <= y);    // true

// Strict equality (checks type too)
console.log('Strict equal:', 5 === '5'); // false

let isStudent = true;
let hasID = true;
let isEmployee = false;

// AND - both must be true
console.log('Student AND has ID:', isStudent && hasID); // true
console.log('Student AND employee:', isStudent && isEmployee); // false

// OR - at least one must be true
console.log('Student OR employee:', isStudent || isEmployee); // true

// NOT - reverses the value
console.log('NOT student:', !isStudent); // false
console.log('NOT employee:', !isEmployee); // true

